<script setup lang="ts">import {ref} from 'vue';import {Head,useForm} from '@inertiajs/vue3';import StoreLayout from '../Layouts/StoreLayout.vue';const p=defineProps<{product:any}>();const selected=ref(p.product.variants[0].id);const form=useForm({quantity:1});const add=()=>form.post(`/cart/${selected.value}`,{preserveScroll:true});const schema={ '@context':'https://schema.org','@type':'Product',name:p.product.name,image:p.product.image_url,description:p.product.description,offers:{'@type':'Offer',priceCurrency:'UAH',price:p.product.variants[0].price_amount/100,availability:'https://schema.org/InStock'}};</script>
<template><Head><title>{{product.seo_title||product.name}}</title><meta name="description" :content="product.seo_description||product.description"/><link rel="canonical" :href="`http://localhost/products/${product.slug}`"/><meta property="og:type" content="product"/><meta property="og:title" :content="product.name"/><component is="script" type="application/ld+json">{{JSON.stringify(schema)}}</component></Head><StoreLayout><section class="product"><img :src="product.image_url" :alt="product.name"><div><p class="eyebrow">{{product.category.name}}</p><h1>{{product.name}}</h1><p class="price">{{(product.variants.find((v:any)=>v.id===selected)?.price_amount/100).toLocaleString('uk-UA')}} ₴</p><p>{{product.description}}</p><p class="muted">Матеріал: {{product.material}}</p><label>Варіант<select v-model="selected"><option v-for="v in product.variants" :value="v.id">{{v.name}} · {{v.stock_on_hand-v.stock_reserved}} шт.</option></select></label><button class="button" @click="add" :disabled="form.processing">Додати до кошика</button></div></section></StoreLayout></template>
